<?php
$type = (string) ($store['resolved_business_type'] ?? $store['business_type'] ?? 'general');
$symbol = match ($store['currency'] ?? 'DOP') { 'USD' => 'US$', 'EUR' => '€', default => 'RD$' };
$typeLabel = match ($type) { 'restaurant' => 'Restaurante', 'electronics' => 'Electrónica y celulares', default => 'Tienda general' };
$roleLabel = match ($store['admin_role'] ?? '') { 'owner' => 'Propietario', 'manager' => 'Gerente', 'cashier' => 'Cajero', 'kitchen' => 'Cocina', default => 'Usuario' };
$money = static fn (mixed $value): string => $symbol . ' ' . number_format((float) $value, 2);
$statusLabel = static fn (string $status): string => match ($status) {
    'pending' => 'Pendiente', 'confirmed' => 'Confirmado', 'preparing' => 'Preparando',
    'ready' => 'Listo', 'dispatched' => 'Despachado', 'delivered' => 'Entregado',
    'completed' => 'Completado', 'cancelled' => 'Cancelado', default => ucfirst($status),
};
$sectionTitle = match ($section) {
    'pos' => $type === 'restaurant' ? 'Nueva orden' : 'Punto de venta',
    'orders' => $type === 'restaurant' ? 'Pedidos y comandas' : 'Ventas y pedidos',
    'dispatched' => 'Pedidos despachados',
    'delivered' => 'Pedidos entregados',
    'products' => $type === 'restaurant' ? 'Menú y productos' : 'Inventario y catálogo',
    'customers' => 'Clientes',
    'operations' => match ($type) { 'restaurant' => 'Cocina y mesas', 'electronics' => 'IMEI, taller y garantías', default => 'Operaciones e inventario' },
    'web' => 'Tienda en línea',
    default => 'Resumen del negocio',
};
$nav = [
    ['dashboard','⌂','Dashboard'], ['pos','＋',$type === 'restaurant' ? 'Nueva orden' : 'Vender'],
    ['orders','▤',$type === 'restaurant' ? 'Pedidos' : 'Ventas'], ['dispatched','🚚','Despachados'],
    ['delivered','✓','Entregados'], ['products','□',$type === 'restaurant' ? 'Menú' : 'Productos'],
    ['customers','◎','Clientes'], ['operations','◇',match($type){'restaurant'=>'Cocina','electronics'=>'Taller e IMEI',default=>'Operaciones'}],
    ['web','↗','Tienda web'],
];
?>
