(()=>{const search=document.querySelector('[data-table-search]');if(search)search.addEventListener('input',()=>{const q=search.value.trim().toLowerCase();document.querySelectorAll('[data-search-row]').forEach(row=>row.hidden=q&&!row.dataset.searchRow.includes(q))});const pSearch=document.querySelector('[data-product-search]'),category=document.querySelector('[data-category]');function filterProducts(){if(!pSearch)return;const q=pSearch.value.trim().toLowerCase(),cat=category.value;document.querySelectorAll('[data-product-card]').forEach(card=>card.hidden=(q&&!card.dataset.search.includes(q))||(cat&&card.dataset.category!==cat))}pSearch?.addEventListener('input',filterProducts);category?.addEventListener('change',filterProducts)})();
