<?php if(in_array($section,['orders','dispatched','delivered'],true)): ?><script>
const orderStatuses=<?= json_encode(array_column($orders,'status','uid'),JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;
const orderInventory=<?= json_encode(array_column($orders,'inventory_status','uid'),JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;
const orderContacts=<?= json_encode(array_combine(array_column($orders,'uid'),array_map(static fn(array $order):array=>['number'=>$order['order_number']??'','phone'=>$order['customer_phone']??'','email'=>$order['customer_email']??''], $orders)) ?: [],JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;
const documentCsrf=<?= json_encode(\App\Core\Csrf::token()) ?>,documentBase=<?= json_encode($adminBase) ?>;
async function shareOrderDocument(uid){
  const contact=orderContacts[uid]||{},url=documentBase+'/orders/'+encodeURIComponent(uid)+'/pdf',message='Hola. Te compartimos el comprobante del pedido '+(contact.number||uid)+'.';
  const nativeShare=typeof navigator.share==='function',fallbackWindow=nativeShare?null:window.open('about:blank','_blank');
  try{
    const response=await fetch(url,{credentials:'same-origin'});if(!response.ok)throw new Error('No se pudo preparar el PDF.');
    const blob=await response.blob(),file=new File([blob],(contact.number||'pedido')+'.pdf',{type:'application/pdf'});
    if(nativeShare&&navigator.canShare?.({files:[file]})){await navigator.share({title:'Pedido '+(contact.number||''),text:message,files:[file]});return}
    const download=document.createElement('a');download.href=URL.createObjectURL(blob);download.download=file.name;download.click();setTimeout(()=>URL.revokeObjectURL(download.href),1500);
    try{await navigator.clipboard.writeText(message+' El PDF fue descargado para que puedas adjuntarlo.')}catch(_){}
    const phone=String(contact.phone||'').replace(/\D/g,''),wa='https://wa.me/'+phone+'?text='+encodeURIComponent(message+' El PDF está listo para adjuntar.');
    if(fallbackWindow)fallbackWindow.location.href=wa;else window.open(wa,'_blank','noopener');
  }catch(error){fallbackWindow?.close();alert(error.message)}
}
async function emailOrderDocument(uid){
  const contact=orderContacts[uid]||{},email=prompt('Correo al que se enviará el PDF:',contact.email||'');if(!email)return;
  try{
    const response=await fetch(documentBase+'/orders/'+encodeURIComponent(uid)+'/email',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({_csrf:documentCsrf,email})});
    const result=await response.json();if(!response.ok)throw new Error(result.message||'No se pudo enviar el correo.');alert(result.message||'Correo enviado correctamente.')
  }catch(error){alert(error.message)}
}
document.querySelectorAll('.status-form').forEach(form=>{
  const select=form.querySelector('select[name="status"]'),row=form.closest('tr'),isWeb=row?.querySelector('.badge')?.textContent.trim()==='Web';
  [['dispatched','Despachado'],['delivered','Entregado']].forEach(([value,label])=>{if(!select.querySelector('option[value="'+value+'"]'))select.add(new Option(label,value))});
  const uid=decodeURIComponent((form.action.split('/orders/')[1]||'').split('/')[0]||''),current=orderStatuses[uid]||select.value;select.value=current;
  if(uid){
    const inventory=document.createElement('span');inventory.className='badge '+(orderInventory[uid]==='committed'?'pos':'warn');inventory.textContent=orderInventory[uid]==='committed'?'Inventario aplicado':orderInventory[uid]==='released'?'Inventario restaurado':'Stock pendiente';form.prepend(inventory);
    const pdf=document.createElement('a');pdf.className='pdf-action';pdf.textContent='Carta';pdf.target='_blank';pdf.rel='noopener';pdf.href=documentBase+'/orders/'+encodeURIComponent(uid)+'/pdf';form.appendChild(pdf);
    const thermal=document.createElement('a');thermal.className='pdf-action thermal';thermal.textContent='80 mm';thermal.target='_blank';thermal.rel='noopener';thermal.href=documentBase+'/orders/'+encodeURIComponent(uid)+'/pdf?format=80mm';form.appendChild(thermal);
    const whatsapp=document.createElement('button');whatsapp.type='button';whatsapp.className='document-action whatsapp';whatsapp.textContent='WhatsApp';whatsapp.onclick=()=>shareOrderDocument(uid);form.appendChild(whatsapp);
    const email=document.createElement('button');email.type='button';email.className='document-action email';email.textContent='Correo';email.onclick=()=>emailOrderDocument(uid);form.appendChild(email);
  }
  if(!isWeb)return;
  if(['pending','confirmed','preparing','ready','completed'].includes(current)){
    const button=document.createElement('button');button.type='button';button.className='dispatch-action';button.textContent='Despachar pedido';button.onclick=()=>{select.value='dispatched';form.submit()};form.appendChild(button);
  }else if(current==='dispatched'){
    const button=document.createElement('button');button.type='button';button.className='dispatch-action deliver';button.textContent='Marcar entregado';button.onclick=()=>{select.value='delivered';form.submit()};form.appendChild(button);
  }
});
</script><?php endif; ?>
<?php if($section==='pos'): ?><script>
(()=>{const products=<?= json_encode(array_column($catalog['products'],null,'uid'),JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>,symbol=<?= json_encode($symbol) ?>,type=<?= json_encode($type) ?>,adminBase=<?= json_encode($adminBase) ?>,csrf=<?= json_encode(\App\Core\Csrf::token()) ?>;let cart={};const cartEl=document.querySelector('[data-cart]'),discountEl=document.querySelector('[data-discount]'),taxEl=document.querySelector('[data-tax]'),money=n=>symbol+' '+Number(n||0).toLocaleString('es-DO',{minimumFractionDigits:2,maximumFractionDigits:2}),escape=v=>{const d=document.createElement('div');d.textContent=String(v??'');return d.innerHTML};function totals(){const subtotal=Object.values(cart).reduce((s,i)=>s+Number(i.product.price)*i.quantity,0),discount=Math.max(0,Math.min(subtotal,Number(discountEl.value)||0)),tax=Math.max(0,Math.min(30,Number(taxEl.value)||0)),total=(subtotal-discount)*(1+tax/100);document.querySelector('[data-subtotal]').textContent=money(subtotal);document.querySelector('[data-total]').textContent=money(total);return{subtotal,discount,tax,total}}function render(){const items=Object.values(cart);cartEl.innerHTML=items.length?items.map(i=>'<div class="cart-line"><div><b>'+escape(i.product.name)+'</b><small>'+money(i.product.price)+'</small><div class="qty-row"><button type="button" data-minus="'+escape(i.product.uid)+'">−</button><span>'+i.quantity+'</span><button type="button" data-plus="'+escape(i.product.uid)+'">+</button><button type="button" data-remove="'+escape(i.product.uid)+'" style="margin-left:6px;color:#dc2626">×</button></div>'+(i.product.kind==='phone'?'<input class="line-note imei-input" data-imei="'+escape(i.product.uid)+'" value="'+escape(i.imei||'')+'" placeholder="IMEI obligatorio">':'')+'<input class="line-note" data-note="'+escape(i.product.uid)+'" value="'+escape(i.note||'')+'" placeholder="'+(type==='restaurant'?'Término, extra o nota de cocina':i.product.kind==='phone'?'Color, capacidad u observación':'Talla, color, variante u observación')+'"></div><b>'+money(Number(i.product.price)*i.quantity)+'</b></div>').join(''):'<div class="cart-empty">Selecciona productos para comenzar.</div>';totals()}document.querySelectorAll('[data-product-card]').forEach(card=>card.addEventListener('click',()=>{const p=products[card.dataset.uid];if(!p)return;cart[p.uid]??={product:p,quantity:0,note:'',imei:''};if(p.stock!==null&&cart[p.uid].quantity>=Number(p.stock))return;if(p.kind==='phone'&&cart[p.uid].quantity>=1)return;cart[p.uid].quantity++;render()}));cartEl.addEventListener('click',e=>{const id=e.target.dataset.plus||e.target.dataset.minus||e.target.dataset.remove;if(!id||!cart[id])return;if(e.target.dataset.plus){if(cart[id].product.kind==='phone'&&cart[id].quantity>=1)return;if(cart[id].product.stock===null||cart[id].quantity<Number(cart[id].product.stock))cart[id].quantity++}else if(e.target.dataset.minus){cart[id].quantity--;if(cart[id].quantity<1)delete cart[id]}else delete cart[id];render()});cartEl.addEventListener('input',e=>{if(e.target.dataset.note&&cart[e.target.dataset.note])cart[e.target.dataset.note].note=e.target.value;if(e.target.dataset.imei&&cart[e.target.dataset.imei])cart[e.target.dataset.imei].imei=e.target.value});discountEl.addEventListener('input',totals);taxEl.addEventListener('input',totals);document.querySelector('[data-clear]').addEventListener('click',()=>{cart={};discountEl.value=0;render()});document.querySelector('[data-complete]').addEventListener('click',async()=>{const button=document.querySelector('[data-complete]'),message=document.querySelector('[data-message]');if(!Object.keys(cart).length)return;const missing=Object.values(cart).find(i=>i.product.kind==='phone'&&!String(i.imei||'').trim());if(missing){message.textContent='Debes indicar el IMEI de '+missing.product.name+'.';message.style.cssText='display:block;background:#fff1f2;color:#9f1239';return}button.disabled=true;message.style.display='none';const data={_csrf:csrf,items:Object.values(cart).map(i=>({uid:i.product.uid,quantity:i.quantity,note:i.note,imei:i.imei})),discount:Number(discountEl.value)||0,tax_rate:Number(taxEl.value)||0,customer_name:document.querySelector('[data-customer]').value,customer_document:document.querySelector('[data-document]').value,customer_phone:document.querySelector('[data-phone]').value,payment_method:document.querySelector('[data-payment]').value,table_reference:document.querySelector('[data-table]')?.value||''};try{const response=await fetch(adminBase+'/pos/sales',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(data)}),result=await response.json();if(!response.ok)throw new Error(result.message||'No se pudo completar la venta.');const printBase=adminBase+'/orders/'+encodeURIComponent(result.data.uid)+'/pdf';message.innerHTML='<strong>Venta '+escape(result.data.order_number)+' registrada por '+money(result.data.total)+'.</strong><div style="display:flex;gap:8px;margin-top:8px"><a target="_blank" href="'+printBase+'" style="font-weight:900">Imprimir carta</a><a target="_blank" href="'+printBase+'?format=80mm" style="font-weight:900">Imprimir 80 mm</a></div>';message.style.cssText='display:block;background:#ecfdf5;color:#047857';cart={};discountEl.value=0;render()}catch(error){message.textContent=error.message;message.style.cssText='display:block;background:#fff1f2;color:#9f1239'}finally{button.disabled=false}});render()})();
</script><?php endif; ?>
